"""Check every team-out file against the clones: SHAs exist, dates match, contract holds, sizes fit, no emails."""
import json
import re
import subprocess
from pathlib import Path

SCR = Path(__file__).parent
WT = Path(r"D:\Atharva\firstrun\.claude\worktrees\agent-a9ab727480efb798e")
EMAIL = re.compile(r"[\w.+-]+@[\w-]+\.[\w.-]+")


def clone_of(repo):
    return SCR / "clones" / re.sub(r"[^a-z0-9]+", "-", repo.lower())


def git_date(clone, sha):
    p = subprocess.run(["git", "-C", str(clone), "show", "-s", "--format=%cI", sha], capture_output=True, text=True)
    return p.stdout.strip()[:10] if p.returncode == 0 else None


problems = 0
for f in sorted((SCR / "team-out").glob("*.json")):
    d = json.loads(f.read_text(encoding="utf-8"))
    bid = f.name.replace(".team-next.json", "")
    board = json.loads((WT / "docs" / "audits" / f"{bid}.json").read_text(encoding="utf-8"))
    clones = [clone_of(board["repo"])] + ([clone_of(board["docs_repo"])] if board.get("docs_repo") else [])
    t, n = d["team"], d["next"]
    text = json.dumps(d, ensure_ascii=False)
    issues = []
    if EMAIL.search(text) or "noreply" in text.lower() or "@" in text:
        issues.append("email-like text")
    tb, nb = len(json.dumps(t, separators=(",", ":"), ensure_ascii=False)), len(json.dumps(n, separators=(",", ":"), ensure_ascii=False))
    if tb >= 10_000 or nb >= 25_000:
        issues.append(f"size team {tb} next {nb}")
    ids = {p["id"] for p in t["people"]}
    if any(c[0] >= len(t["people"]) or c[0] < -1 or not 0 <= c[1] < len(t["areas"]) for c in t["cells"]):
        issues.append("cell out of range")
    if [i["rank"] for i in n["items"]] != list(range(1, len(n["items"]) + 1)):
        issues.append("ranks")
    shas = dates = 0
    for it in n["items"]:
        for k in ("owner", "runner_up"):
            if it.get(k) and it[k]["p"] not in ids:
                issues.append(f"{k} id {it[k]['p']} missing")
        if it["effort"] not in "SML" or not 0 <= it["score"] <= 100:
            issues.append("effort/score")
        for e in it["evidence"]:
            shas += 1
            got = next((git_date(c, e["sha"]) for c in clones if git_date(c, e["sha"])), None)
            if got is None:
                issues.append(f"sha {e['sha']} not in clone")
            elif got != e["date"]:
                dates += 1
        for s in re.findall(r"\b[0-9a-f]{9}\b", it["rationale"] + " " + ((it.get("owner") or {}).get("why") or "")):
            if not any(git_date(c, s) for c in clones):
                issues.append(f"cited sha {s} not in clone")
        if "  " in it["title"] or "—" in it["rationale"].replace(it["evidence"][0]["subject"] if it["evidence"] else "", ""):
            pass
    print(f"{bid}: people {len(t['people'])}, areas {len(t['areas'])}, items {len(n['items'])}, team {tb} B, next {nb} B, "
          f"{shas} evidence shas checked, {dates} dates differ, issues: {issues or 'none'}")
    problems += len(issues)
print("problems:", problems)

